from pydantic import BaseModel, Field

class Paper(BaseModel):
    """One provided paper: its own title and which of the OTHER provided papers it references."""
    title: str | None = Field(description="The title of this paper as it appears in the document")
    references_to_provided_papers: list[str] = Field(
        description="Titles of the OTHER provided papers (known from the collection) that appear in this paper's reference list"
    )

class Parse(BaseModel):
    papers: list[Paper]
